contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log) public payable {
        require(_log != address(0));

        uint256 balBefore = address(c).balance;

        bool firstReverted;
        c.SetLogFile(address(0)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool secondReverted;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(secondReverted == firstReverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

